#include "core.h"

// MD TRX: generated by tools/make_engine.py. Each key holds its own machine,
// chosen with Shift and the first encoder, and that machine's eight controls
// (kit.h), which the SDK saves with the project. The sound is in the voice
// modules: TRX-BD (voices/trx_bd.hpp), TRX-SD (voices/trx_sd.hpp), TRX-XT (voices/trx_tom.hpp), TRX-CP (voices/trx_cp.hpp), TRX-RS (voices/trx_rs.hpp), TRX-CB (voices/trx_cb.hpp), TRX-CH (voices/trx_hat.hpp), TRX-OH (voices/trx_hat.hpp), TRX-CY (voices/trx_cy.hpp), TRX-MA (voices/trx_ma.hpp), TRX-CL (voices/trx_cl.hpp), TRX-XC (voices/trx_tom.hpp), TRX-B2 (voices/trx_b2.hpp).
namespace mdtrx {
void drum_defaults(u32 key, opxy::u8* model, opxy::u8* controls) {
    const u32 k = key >= 53 && key < 53 + kit::keys ? key - 53 : 0;
    *model = kit::key_model[k];
    for (u32 c = 0; c < 8; ++c) controls[c] = kit::key_values[k][c];
}
const char* model_name(u32 model) { return kit::model[model < kit::models ? model : 0].name; }
const char* parameter_name(u32 model, u32 slot) {
    return slot < 8 ? kit::model[model < kit::models ? model : 0].labels[slot] : "";
}
u32 parameter_count(u32 model) { return kit::model[model < kit::models ? model : 0].count; }

inline void begin_member(Voice& voice, Shared& shared) {
    switch (voice.machine) {
    case 0: md::trx_bd::reset(voice.u.m0, shared.common, voice.owner); break;
    case 1: md::trx_sd::reset(voice.u.m1, shared.common, voice.owner); break;
    case 2: md::trx_xt::reset(voice.u.m2, shared.common, voice.owner); break;
    case 3: md::trx_cp::reset(voice.u.m3, shared.common, voice.owner); break;
    case 4: md::trx_rs::reset(voice.u.m4, shared.common, voice.owner); break;
    case 5: md::trx_cb::reset(voice.u.m5, shared.common, voice.owner); break;
    case 6: md::trx_ch::reset(voice.u.m6, shared.common, voice.owner); break;
    case 7: md::trx_oh::reset(voice.u.m7, shared.common, voice.owner); break;
    case 8: md::trx_cy::reset(voice.u.m8, shared.common, voice.owner); break;
    case 9: md::trx_ma::reset(voice.u.m9, shared.common, voice.owner); break;
    case 10: md::trx_cl::reset(voice.u.m10, shared.common, voice.owner); break;
    case 11: md::trx_xc::reset(voice.u.m11, shared.common, voice.owner); break;
    case 12: md::trx_b2::reset(voice.u.m12, shared.common, voice.owner); break;
    default: return;
    }
    switch (voice.machine) {
    case 0: md::trx_bd::trigger(voice.u.m0, shared.common); break;
    case 1: md::trx_sd::trigger(voice.u.m1, shared.common); break;
    case 2: md::trx_xt::trigger(voice.u.m2, shared.common); break;
    case 3: md::trx_cp::trigger(voice.u.m3, shared.common); break;
    case 4: md::trx_rs::trigger(voice.u.m4, shared.common); break;
    case 5: md::trx_cb::trigger(voice.u.m5, shared.common); break;
    case 6: md::trx_ch::trigger(voice.u.m6, shared.common); break;
    case 7: md::trx_oh::trigger(voice.u.m7, shared.common); break;
    case 8: md::trx_cy::trigger(voice.u.m8, shared.common); break;
    case 9: md::trx_ma::trigger(voice.u.m9, shared.common); break;
    case 10: md::trx_cl::trigger(voice.u.m10, shared.common); break;
    case 11: md::trx_xc::trigger(voice.u.m11, shared.common); break;
    case 12: md::trx_b2::trigger(voice.u.m12, shared.common); break;
    default: break;
    }
}

inline void initialize(Voice& voice, Shared&, u32 owner) {
    voice.machine = 0;
    voice.next = 0;
    voice.owner = owner;
    voice.pending = 0;
}
inline void start(Voice& voice, Shared&, u32) { voice.pending = 1; }
inline void destroy(Voice&, Shared&, u32) {}
inline void drum_select(Voice& voice, Shared&, u32, u32 model) { voice.next = model < kit::models ? model : 0; }

// The machines are voiced at middle C and tuned by their own PTCH, as on the
// original, so the note's pitch is not used.
inline void render(Voice& voice, Shared& shared, u32, opxy::Output output, opxy::Parameters parameters, opxy::Pitch) {
    if (voice.pending || voice.next != voice.machine) {
        voice.pending = 0;
        voice.machine = voice.next;
        begin_member(voice, shared);
    }
    i32 own[8];
    kit::controls(voice.machine, parameters, own);
    u32 tuned[opxy::block_frames];
    for (unsigned i = 0; i < opxy::block_frames; ++i) tuned[i] = ::md::kit::middle_c;
    switch (voice.machine) {
    case 0: md::trx_bd::render(voice.u.m0, shared.common, output, own, tuned); break;
    case 1: md::trx_sd::render(voice.u.m1, shared.common, output, own, tuned); break;
    case 2: md::trx_xt::render(voice.u.m2, shared.common, output, own, tuned); break;
    case 3: md::trx_cp::render(voice.u.m3, shared.common, output, own, tuned); break;
    case 4: md::trx_rs::render(voice.u.m4, shared.common, output, own, tuned); break;
    case 5: md::trx_cb::render(voice.u.m5, shared.common, output, own, tuned); break;
    case 6: md::trx_ch::render(voice.u.m6, shared.common, output, own, tuned); break;
    case 7: md::trx_oh::render(voice.u.m7, shared.common, output, own, tuned); break;
    case 8: md::trx_cy::render(voice.u.m8, shared.common, output, own, tuned); break;
    case 9: md::trx_ma::render(voice.u.m9, shared.common, output, own, tuned); break;
    case 10: md::trx_cl::render(voice.u.m10, shared.common, output, own, tuned); break;
    case 11: md::trx_xc::render(voice.u.m11, shared.common, output, own, tuned); break;
    case 12: md::trx_b2::render(voice.u.m12, shared.common, output, own, tuned); break;
    default: for (unsigned i = 0; i < opxy::block_frames; ++i) output[i] = 0; break;
    }
}
}
